suppressPackageStartupMessages(library(tidyverse))
src<-'./output/research_extensions/28_paper_state_guarded_refresh';out<-'output/paper_assets';dir.create(out,recursive=TRUE,showWarnings=FALSE)
th<-theme_bw(base_size=11)+theme(panel.grid.minor=element_blank(),panel.grid.major.x=element_blank(),strip.background=element_blank(),strip.text=element_text(face='bold',colour='#214F80'),legend.position='bottom',legend.title=element_blank())
b<-read_csv(file.path(src,'descriptives/balance_summary.csv'),show_col_types=FALSE)
nice<-c(log_rac='Log resident-held jobs',log_wac='Log workplace jobs',log_seer_pop='Log population',rac_low_share='Low-wage share (RAC)',rac_high_share='High-wage share (RAC)',wac_low_share='Low-wage share (WAC)',wac_high_share='High-wage share (WAC)',seer_share_nh_black='Share non-Hispanic Black',seer_share_nh_aian='Share NH American Indian / Alaska Native',seer_share_nh_api='Share NH Asian / Pacific Islander',seer_share_hispanic='Share Hispanic',seer_age_share_under29='Share age under 29',seer_age_share_55plus='Share age 55+')
for(k in c('recent','early'))for(v in c('log_rac','log_wac','log_seer_pop','rac_total','wac_total'))nice[paste0(v,'_',k)]<-paste(if(k=='recent')'Recent' else 'Earlier',c(log_rac='log RAC growth',log_wac='log WAC growth',log_seer_pop='log population growth',rac_total='RAC absolute growth',wac_total='WAC absolute growth')[v])
stopifnot(all(b$covariate%in%names(nice)))
b<-b%>%mutate(group=factor(group,levels=c('pooled','lower_income','higher_income'),labels=c('Pooled','Lower income','Higher income')),stage=factor(stage,levels=c('before','after'),labels=c('Before matching','After matching')),variable=factor(covariate,levels=rev(names(nice)),labels=rev(unname(nice))))
p<-ggplot(b,aes(mean_absolute_smd,variable,colour=stage))+geom_vline(xintercept=.1,linetype=2,colour='grey60')+geom_point(size=1.9)+facet_wrap(~group,nrow=1)+scale_color_manual(values=c('#829BB2','#214F80'))+th+labs(x='Matched-cohort-weighted mean absolute standardized difference',y=NULL)
ggsave(file.path(out,'balance.pdf'),p,width=13,height=8.5);ggsave(file.path(out,'balance.png'),p,width=13,height=8.5,dpi=160)
a<-read_csv(file.path(src,'all_event_study.csv'),show_col_types=FALSE)%>%filter(analysis=='near_far',specification=='matched_pair_year',outcome%in%c('near_per_pop_10','far_per_pop_10','log_near_jobs_10','log_far_jobs_10'))%>%mutate(event=as.numeric(sub('year::','',term)),measure=if_else(str_starts(outcome,'log'),'Log jobs','Employment-to-population ratio (pp)'),distance=if_else(str_detect(outcome,'near'),'Nearby','Farther'),estimate=estimate*if_else(str_starts(outcome,'log'),1,100),std_error=std_error*if_else(str_starts(outcome,'log'),1,100))%>%filter(between(event,-5,5))
a<-bind_rows(a,distinct(a,measure,distance)%>%mutate(event=-1,estimate=0,std_error=0))%>%mutate(distance=factor(distance,levels=c('Nearby','Farther')))
p<-ggplot(a,aes(event,estimate))+geom_hline(yintercept=0,colour='grey60')+geom_vline(xintercept=-1,linetype=2,colour='grey60')+geom_errorbar(aes(ymin=estimate-1.96*std_error,ymax=estimate+1.96*std_error),width=.08,colour='#214F80')+geom_line(colour='#214F80')+geom_point(colour='#214F80',size=1.4)+facet_grid(measure~distance,scales='free_y')+scale_x_continuous(breaks=-5:5)+th+labs(x='Years relative to first placement',y=NULL)
ggsave(file.path(out,'near_far.pdf'),p,width=10,height=7)
a<-read_csv(file.path(src,'all_att.csv'),show_col_types=FALSE)%>%filter(analysis=='near_far',specification=='matched_pair_year',str_detect(outcome,'^(near_per_pop|far_per_pop|log_near_jobs|log_far_jobs)_'))%>%mutate(radius=as.numeric(sub('.*_','',outcome)),measure=if_else(str_starts(outcome,'log'),'Log jobs','Employment-to-population ratio (pp)'),distance=if_else(str_detect(outcome,'near'),'Nearby','Farther'),estimate=estimate*if_else(str_starts(outcome,'log'),1,100),std_error=std_error*if_else(str_starts(outcome,'log'),1,100))
p<-ggplot(a,aes(radius,estimate,colour=distance))+geom_hline(yintercept=0,colour='grey60')+geom_errorbar(aes(ymin=estimate-1.96*std_error,ymax=estimate+1.96*std_error),width=.3,position=position_dodge(.8))+geom_point(position=position_dodge(.8))+facet_wrap(~measure,ncol=1,scales='free_y')+scale_x_continuous(breaks=c(5,10,20))+scale_color_manual(values=c('#B1672F','#214F80'))+th+labs(x='Radius (km)',y=NULL)
ggsave(file.path(out,'radius.pdf'),p,width=9,height=6)
